<template><div class="file-list"><div class="list-head"><span class="name-head">Name <span class="sort">↑</span></span><span>Type</span><span>Modified</span><span></span></div>
<FileItem v-for="folder in library.visibleFolders.value" :key="'folder-'+folder.id" :icon="folder.icon" :name="folder.name" type="Folder" :selected="library.selectedFolder.value?.id===folder.id" :modified="formatModified(folder.modified_at)" @click="selectFolder(folder)" @open="openFolder(folder)"/>
<FileItem v-for="file in files" :key="file.id" :icon="file.icon" :name="file.name" type="Media" :selected="library.selectedFile.value?.id===file.id" :modified="formatModified(file.modified_at)" @click="selectFile(file)" @open="downloadFile(file)" @more="openMenu(file,$event)"/>
<div v-if="library.visibleFolders.value.length===0&&files.length===0" class="empty">This folder is empty.</div>
<Teleport to="body"><FileContextMenu v-if="menuFile" :open="true" :dark="dark" :x="menuX" :y="menuY" @play-vlc="playByVlc(menuFile)" @play-mx="playByMx(menuFile)" @copy-url="copyUrl(menuFile)"/></Teleport></div></template>
<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from "vue";import FileItem from "./FileItem.vue";import FileContextMenu from "./FileContextMenu.vue";import {useLibrary} from "../stores/library";import type {Folder,MediaFile} from "../types/media";defineProps<{files:MediaFile[];dark:boolean}>();const library=useLibrary();const menuFile=ref<MediaFile|null>(null),menuX=ref(0),menuY=ref(0);const menuWidth=190,menuHeight=170,menuGap=8;
function selectFolder(folder:Folder){closeMenu();library.selectFolder(folder)}async function openFolder(folder:Folder){closeMenu();await library.openFolder(folder.id)}function selectFile(file:MediaFile){closeMenu();library.selectFile(file)}
function formatModified(value?:string|null){if(!value)return"—";const date=new Date(value);return Number.isNaN(date.getTime())?"—":date.toISOString().slice(0,16).replace("T"," ")}
function downloadFile(file:MediaFile){closeMenu();const a=document.createElement("a");a.href=file.stream_url;a.download=file.name;a.target="_blank";a.rel="noopener";document.body.appendChild(a);a.click();a.remove()}
function openMenu(file:MediaFile,button:HTMLElement){library.selectFile(file);menuFile.value=file;const r=button.getBoundingClientRect(),right=r.right+menuGap+menuWidth<=window.innerWidth-8,left=r.left-menuGap-menuWidth>=8;const x=right?r.right+menuGap:left?r.left-menuWidth-menuGap:window.innerWidth-menuWidth-8,y=r.top+menuHeight>window.innerHeight-8?window.innerHeight-menuHeight-8:r.top;menuX.value=Math.max(8,x);menuY.value=Math.max(8,y)}
function closeMenu(){menuFile.value=null}async function copyUrl(file:MediaFile|null){if(!file)return;closeMenu();try{await navigator.clipboard.writeText(file.stream_url);window.alert("URL copied to clipboard")}catch(e){console.error(e);window.alert("Clipboard access failed")}}
function openIntent(file:MediaFile|null,app:string){if(!file)return;closeMenu();try{const u=new URL(file.stream_url),scheme=u.protocol.slice(0,-1),intent="android-app://"+app+"/"+scheme+"/"+u.host+u.pathname+u.search+u.hash,a=document.createElement("a");a.href=intent;a.target="_self";a.rel="noopener";document.body.appendChild(a);a.click();a.remove()}catch(e){console.error(e);window.alert("Invalid media URL")}}
function playByVlc(file:MediaFile|null){openIntent(file,"org.videolan.vlc")}function playByMx(file:MediaFile|null){openIntent(file,"com.mxtech.videoplayer.ad")}
function handleDocumentClick(event:MouseEvent){const t=event.target as HTMLElement|null;if(t?.closest(".context-menu")||t?.closest(".more"))return;closeMenu()}function handleEscape(event:KeyboardEvent){if(event.key==="Escape")closeMenu()}function handleResize(){closeMenu()}
onMounted(()=>{document.addEventListener("click",handleDocumentClick);window.addEventListener("keydown",handleEscape);window.addEventListener("resize",handleResize);window.addEventListener("scroll",closeMenu,true)})
onBeforeUnmount(()=>{document.removeEventListener("click",handleDocumentClick);window.removeEventListener("keydown",handleEscape);window.removeEventListener("resize",handleResize);window.removeEventListener("scroll",closeMenu,true)})
</script>
<style scoped>
.file-list{flex:1;min-height:0;overflow:auto;background:var(--content-bg)}.list-head{min-height:42px;display:grid;grid-template-columns:48px minmax(180px,1fr) minmax(90px,18%) minmax(150px,18%) 38px;align-items:center;gap:8px;padding:0 22px;background:linear-gradient(180deg,var(--header-bg-1),var(--header-bg-2));border-bottom:1px solid var(--border);color:var(--text-2);font-size:13px;font-weight:700;position:sticky;top:0;z-index:2}.list-head .name-head{grid-column:1/3}.sort{margin-left:4px;color:var(--accent-strong)}.empty{display:flex;justify-content:center;align-items:center;height:calc(100% - 42px);min-height:180px;color:var(--text-3);font-size:15px}@media(max-width:760px){.list-head{grid-template-columns:42px minmax(150px,1fr) 80px 34px;padding:0 12px}.list-head .name-head{grid-column:1/3}.list-head span:nth-child(3){display:none}}
</style>